import { Injectable } from '@angular/core';
import { environment } from '../../../../environments/environment';
import { HttpClient, HttpParams } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class PresentToolService {

  url: string = environment.presentationservice;
  constructor(private http: HttpClient) { }




  async getPresentInfo(nPresentid: string): Promise<any> {
    const params = new HttpParams().set('nPresentid', nPresentid);
    let res: any = {};
    try {
      res = await firstValueFrom(
        this.http.get<any>(
          `${this.url}/present/tool/detail`, { params: params }
        )
      );
      res = res[0];
    } catch (error) {
      console.error(error)
      res = {};
    }
    return res;
  }





  async getPresentUsers(nPresentid: string): Promise<any> {
    const params = new HttpParams().set('nPresentid', nPresentid);
    let res: any = {};
    try {
      res = await firstValueFrom(
        this.http.get<any>(
          `${this.url}/present/tool/users`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = {};
    }
    return res;
  }


  async managePresentUsers(nPresentid: string, nUserid: string, cPermission: 'N' | 'E' | 'D', cStatus?: 'A' | 'I') {
    let res: any = {};
    const obj = {
      nPresentid: nPresentid,
      nUserid: nUserid,
      cPermission: cPermission,
      cStatus: cStatus || 'A'
    }
    try {
      res = await firstValueFrom(
        this.http.post<any>(`${this.url}/present/tool/manage/user`, obj)
      );
      res[0]
    } catch (error) {
      console.error(error)
      res = { msg: -1, error: error };
    }
    return res;
  }



  async manageUserRequest(nPresentid: string, nUserid: string, cStatus?: 'A' | 'R') {
    let res: any = {};
    const obj = {
      nPresentid: nPresentid,
      nUserid: nUserid,
      cStatus: cStatus || 'A'
    }
    try {
      res = await firstValueFrom(
        this.http.post<any>(`${this.url}/present/tool/manage/request`, obj)
      );
    } catch (error) {
      console.error(error)
      res = { msg: -1, error: error };
    }
    return res;
  }


  async managePresentStatus(nPresentid: string, cStatus: 'P' | 'L' | 'C'): Promise<any> {
    let res: any = {};
    const obj = {
      nPresentid: nPresentid,
      cStatus: cStatus
    }
    try {
      res = await firstValueFrom(
        this.http.post<any>(`${this.url}/present/tool/manage/status`, obj)
      );
      res = res[0];
    } catch (error) {
      console.error(error)
      res = { msg: -1, error: error };
    }
    return res;
  }


}
